const settlementQueues = new WeakMap()

function notifySettled(ledger, hook, payload) {
  if (typeof hook !== 'function') return

  let state = settlementQueues.get(ledger)
  if (state === undefined) {
    state = { draining: false, queue: [] }
    settlementQueues.set(ledger, state)
  }
  state.queue.push({ hook, payload })
  if (state.draining) return

  state.draining = true
  try {
    while (state.queue.length > 0) {
      const settlement = state.queue.shift()
      settlement.hook(settlement.payload)
    }
  } finally {
    state.draining = false
    state.queue.length = 0
  }
